// ⚠️ Nodo de ejemplo. Reemplázalo por la lectura del Excel:
//   Read Binary File → Spreadsheet File (xlsx) → (este mapeo).
// Cada item de salida = UNA fila de la asociación grupo-paciente.
// El nodo Postgres siguiente se ejecuta una vez por item (fila).
//
// Columnas del Excel:
//   ID_GRUPO_PACIENTE → se busca en groups.external_id  (→ group_id real)
//   ID_PACIENTE       → se busca en users.internal_id     (→ patient_id real)
const rows = [
  { ID_GRUPO_PACIENTE: 'EXT-001', ID_PACIENTE: 'PAC-100' }
];

return rows.map((r) => ({ json: r }));

// Junta el resultado de todas las filas procesadas en un solo objeto.
// 'matched' = filas que resolvieron ambos ids y se insertaron/actualizaron.
// 'unmatched' = filas donde faltó el grupo o el paciente (para depurar).
const items = $input.all();
const results = items.map((i) => i.json.result).filter(Boolean);

const matched = results.filter((r) => r.group_patient);
const unmatched = results
  .filter((r) => !r.group_patient)
  .map((r) => r.resolved);

return [{
  json: {
    count: matched.length,
    group_patients: matched.map((r) => r.group_patient),
    unmatched_count: unmatched.length,
    unmatched
  }
}];
